export * from "./transaction.types";

export * from "./account.types";

export * from "./id.types";

export * from "./response.types";

import { useEffect, useState, useCallback } from "react"
import { useSearch } from "@tanstack/react-router"
import { MoreVertical } from "lucide-react"
import { signOut, useSession } from "../lib/auth-client"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Input } from "../components/ui/input"
import { Label } from "../components/ui/label"
import { Skeleton } from "../components/ui/skeleton"
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
} from "../components/ui/dropdown-menu"
import ProfileSection from "../components/ProfileSection"
import WalletCardCarousel from "../components/WalletCardCarousel"
import type { IWalletTransaction, WaveResponse, ITransaction, TBankAccountNumber } from "@/types"
import { createAccount, fetchAccountData } from "@/actions/account.actions"

type ApiResponse<T> = WaveResponse<T>

export default function AccountPage() {
  const { data: session } = useSession()
  const user = session!.user
  const search = useSearch({ strict: false }) as { section?: string }
  const initialSection = search.section ?? null

  const [accounts, setAccounts] = useState<IWalletTransaction[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [creating, setCreating] = useState(false)
  const [createError, setCreateError] = useState<string | null>(null)
  const [accountName, setAccountName] = useState("")

  const [depositAccountNumber, setDepositAccountNumber] = useState<TBankAccountNumber>();
  const [depositAmount, setDepositAmount] = useState("");
  const [depositing, setDepositing] = useState(false);
  const [depositError, setDepositError] = useState<string | null>(null);
  const [depositSuccess, setDepositSuccess] = useState<IWalletTransaction | null>(null);

  const [transferring, setTransferring] = useState(false);
  const [transferError, setTransferError] = useState<string | null>(null);
  const [transferSuccess, setTransferSuccess] = useState<ITransaction | null>(null);
  const [senderAccountNumber, setSenderAccountNumber] = useState<TBankAccountNumber>();
  const [receiverNumber, setReceiverNumber] = useState("")
  const [amount, setAmount] = useState("")
  const [receiverLookup, setReceiverLookup] = useState<{ name: string; accountNumber: TBankAccountNumber } | null>(null)
  const [lookingUp, setLookingUp] = useState(false)

  const fetchAccounts = useCallback(async () => {
    try {
      setLoading(true)
      setError(null)

      const res = await fetchAccountData(user.id);
      if(!res.ok) {
        setAccounts([])
        setError(res.message || "Failed to load accounts")

        return;
      }

      setAccounts(res.data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load accounts")
      setAccounts([])
    } finally {
      setError(null);
      setLoading(false);
    }
  }, [user.id])

  useEffect(() => {
    fetchAccounts()
  }, [fetchAccounts])

  useEffect(() => {
    if (initialSection === "deposit") {
      const el = document.getElementById("deposit-section")
      if (el) el.scrollIntoView({ behavior: "smooth" })
      setDepositAccountNumber(accounts.length > 0 ? accounts[0]!.accountNumber : undefined)
    }
  }, [initialSection, accounts])

  useEffect(() => {
    if (!receiverNumber.trim() || receiverNumber.length < 8) {
      setReceiverLookup(null)
      return
    }
    const timer = setTimeout(async () => {
      setLookingUp(true)
      try {
        const res = await fetch(`/api/wallet/accounts/by-number/${encodeURIComponent(receiverNumber.trim())}`)
        const json: ApiResponse<IWalletTransaction> = await res.json()
        if (json.ok) {
          setReceiverLookup({
            accountNumber: json.data.accountNumber,
            name: json.data.name,
          })
        }
      } catch {
        setReceiverLookup(null)
      } finally {
        setLookingUp(false)
      }
    }, 400)
    return () => clearTimeout(timer)
  }, [receiverNumber])

  const handleCreateAccount = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!accountName.trim()) return

    setCreating(true)
    setCreateError(null)

    const accountNumber = String(Math.floor(Math.random() * 9_000_000_000_000) + 1_000_000_000_000) as unknown as TBankAccountNumber;

    try {
      const res = await createAccount({
        userId: user.id,
        name: accountName.trim(),
        accountNumber,
        balance: 0,
      });

      if (!res.ok) {
        throw new Error(res.error ?? `HTTP ${res.status}`)
      }
      setAccounts((prev) => [...prev, res.data])
      setAccountName("")
    } catch (err) {
      setCreateError(err instanceof Error ? err.message : "Failed to create account")
    } finally {
      setCreating(false)
    }
  }

  const handleDeposit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!depositAccountNumber || !depositAmount.trim()) return

    setDepositing(true)
    setDepositError(null)
    setDepositSuccess(null)

    try {
      const res = await fetch("/api/wallet/accounts/" + depositAccountNumber + "/deposit", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          userId: user.id,
          accountNumber: depositAccountNumber,
          amount: Number.parseFloat(depositAmount),
        }),
      })
      const json: ApiResponse<IWalletTransaction> = await res.json()
      if (!json.ok) throw new Error(json.error ?? `HTTP ${res.status}`)
      setDepositSuccess(json.data)
      setDepositAmount(json.data.balance.toString())
      fetchAccounts()
    } catch (err) {
      setDepositError(err instanceof Error ? err.message : "Failed to deposit funds")
    } finally {
      setDepositing(false)
    }
  }

  const handleTransfer = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!senderAccountNumber || !receiverLookup || !amount.trim()) return

    setTransferring(true)
    setTransferError(null)
    setTransferSuccess(null)

    const sender = accounts.find((a) => a.accountNumber === senderAccountNumber)

    try {
      const res = await fetch("/api/wallet/transfers", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          userId: user.id,
          senderAccountNumber: senderAccountNumber,
          senderName: sender?.name ?? "Unknown",
          receiverAccountNumber: receiverLookup.accountNumber,
          receiverName: receiverLookup.name,
          amount: Number.parseFloat(amount),
        }),
      })
      const json: ApiResponse<ITransaction> = await res.json()
      if (!json.ok) throw new Error(json.error ?? `HTTP ${res.status}`)
      setTransferSuccess(json.data)
      setSenderAccountNumber(json.data.senderAccountNumber)
      setReceiverNumber("")
      setAmount("")
      setReceiverLookup(null)
      fetchAccounts()
    } catch (err) {
      setTransferError(err instanceof Error ? err.message : "Failed to send transfer")
    } finally {
      setTransferring(false)
    }
  }



  const handleSignOut = async () => {
    await signOut()
  }

  const formatCurrency = (value: number | string) =>
    new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(Number(value))

  return (
    <>
      <header className="flex items-center justify-between flex-wrap gap-3 px-8 py-5 border-b border-border">
        <h1 className="text-xl font-semibold tracking-tight text-foreground">Account</h1>
        <div className="flex items-center gap-3">
          <span className="text-sm text-muted-foreground">{user.email}</span>
          <Button variant="outline" size="sm" onClick={fetchAccounts} disabled={loading}>
            Refresh
          </Button>
          <div className="relative">
            <DropdownMenu>
              <DropdownMenuTrigger className="h-9 w-9 rounded-md border border-input bg-background hover:bg-accent hover:text-accent-foreground">
                <MoreVertical className="size-4" />
              </DropdownMenuTrigger>
              <DropdownMenuContent>
                <DropdownMenuItem onClick={() => window.location.href = "/account/settings"}>
                  Edit
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={() => window.location.href = "/account/transactions"}>
                  Transactions
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={handleSignOut}>
                  Sign Out
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </div>
      </header>

      <main className="flex-1 mx-auto w-full max-w-2xl px-8 py-8 space-y-6">
        <ProfileSection />

        <Card>
          <CardHeader className="flex flex-row items-center justify-between">
            <CardTitle>Wallet Accounts</CardTitle>
            <span className="text-xs text-muted-foreground">{accounts.length} total</span>
          </CardHeader>
          <CardContent className="space-y-3">
            {loading && (
              <div className="space-y-3">
                {Array.from({ length: 2 }).map((_, i) => (
                  <Skeleton key={i} className="h-16 w-full rounded-lg" />
                ))}
              </div>
            )}

            {error && !loading && (
              <div className="flex flex-col items-center gap-3 py-6 text-center">
                <p className="text-sm text-muted-foreground">{error}</p>
                <Button variant="outline" size="sm" onClick={fetchAccounts}>
                  Retry
                </Button>
              </div>
            )}

            {!loading && !error && accounts.length === 0 && (
              <div className="py-6 text-center">
                <p className="text-sm text-muted-foreground">No accounts yet. Create one below.</p>
              </div>
            )}

            {!loading && !error && accounts.length > 0 && (
              <WalletCardCarousel accounts={accounts} />
            )}

            <form onSubmit={handleCreateAccount} className="space-y-3 pt-4 border-t border-border">
              <div className="space-y-1.5">
                <Label htmlFor="account-name">New Account Name</Label>
                <Input
                  id="account-name"
                  placeholder="e.g. Checking, Savings"
                  value={accountName}
                  onChange={(e) => setAccountName(e.target.value)}
                  disabled={creating}
                />
              </div>
              {createError && (
                <p className="text-sm text-destructive">{createError}</p>
              )}
              <Button type="submit" disabled={creating || !accountName.trim()} className="w-full">
                {creating ? "Creating..." : "Create Account"}
              </Button>
            </form>
          </CardContent>
        </Card>

        <Card id="deposit-section">
          <CardHeader>
            <CardTitle>Add Money</CardTitle>
          </CardHeader>
          <CardContent>
            {depositSuccess ? (
              <div className="space-y-4">
                <div className="rounded-lg bg-success/8 p-5 text-center space-y-1">
                  <p className="text-sm font-semibold text-success">Deposit completed</p>
                  <p className="text-lg font-mono font-bold text-foreground">
                    {formatCurrency(depositSuccess.balance)}
                  </p>
                  <p className="text-xs text-muted-foreground">{depositSuccess.name}</p>
                </div>
                <Button variant="outline" size="sm" className="w-full" onClick={() => setDepositSuccess(null)}>
                  Deposit again
                </Button>
              </div>
            ) : (
              <form onSubmit={handleDeposit} className="space-y-4">
                <div className="space-y-1.5">
                  <Label htmlFor="deposit-account">Into</Label>
                    <select
                      id="deposit-account"
                      value={depositAccountNumber as unknown as string}
                      onChange={(e) => setDepositAccountNumber(e.target.value as unknown as TBankAccountNumber)}
                      className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                      required
                    >
                      <option value="" disabled>Select an account</option>
                      {accounts.map((acc) => (
                        <option key={acc.id} value={acc.accountNumber as unknown as number}>
                          {acc.name} ({acc.accountNumber}) · {formatCurrency(acc.balance)}
                        </option>
                      ))}
                    </select>
                </div>
                <div className="space-y-1.5">
                  <Label htmlFor="deposit-amount">Amount (USD)</Label>
                  <Input
                    id="deposit-amount"
                    type="number"
                    step="0.01"
                    min="0.01"
                    placeholder="0.00"
                    value={depositAmount}
                    onChange={(e) => setDepositAmount(e.target.value)}
                  />
                </div>
                {depositError && (
                  <p className="text-sm text-destructive">{depositError}</p>
                )}
                <Button
                  type="submit"
                  disabled={!depositAccountNumber || Number(depositAmount) <= 0}
                  className="w-full"
                >
                  Add Money
                </Button>
              </form>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Send Money</CardTitle>
          </CardHeader>
          <CardContent>
            {transferSuccess ? (
              <div className="space-y-4">
                <div className="rounded-lg bg-success/8 p-5 text-center space-y-1">
                  <p className="text-sm font-semibold text-success">Transfer completed</p>
                  <p className="text-lg font-mono font-bold text-foreground">
                    {formatCurrency(transferSuccess.amount)}
                  </p>
                  <p className="text-xs text-muted-foreground">
                    {transferSuccess.senderName} &rarr; {transferSuccess.receiverName}
                  </p>
                </div>
                <Button variant="outline" size="sm" className="w-full" onClick={() => setTransferSuccess(null)}>
                  Send another
                </Button>
              </div>
            ) : (
              <form onSubmit={handleTransfer} className="space-y-4">
                <div className="space-y-1.5">
                  <Label htmlFor="sender">From</Label>
                    <select
                      id="sender"
                      value={senderAccountNumber as unknown as number}
                      onChange={(e) => setSenderAccountNumber(e.target.value as unknown as TBankAccountNumber)}
                      className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                      required
                    >
                      <option value="" disabled>Select an account</option>
                      {accounts.map((acc) => (
                        <option key={acc.id} value={acc.accountNumber as unknown as number}>
                          {acc.name} ({acc.accountNumber}) · {formatCurrency(acc.balance)}
                        </option>
                      ))}
                    </select>
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="receiver">To (account number)</Label>
                  <Input
                    id="receiver"
                    placeholder="e.g. 1000000000000"
                    value={receiverNumber}
                    onChange={(e) => setReceiverNumber(e.target.value)}
                  />
                  {lookingUp && (
                    <p className="text-xs text-muted-foreground">Looking up account...</p>
                  )}
                  {receiverLookup && !lookingUp && (
                    <p className="text-xs font-medium text-success">{receiverLookup.name}</p>
                  )}
                  {!receiverLookup && !lookingUp && receiverNumber.length >= 8 && (
                    <p className="text-xs text-muted-foreground">No account found with that number</p>
                  )}
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="amount">Amount (USD)</Label>
                  <Input
                    id="amount"
                    type="number"
                    step="0.01"
                    min="0.01"
                    placeholder="0.00"
                    value={amount}
                    onChange={(e) => setAmount(e.target.value)}
                  />
                </div>

                {transferError && (
                  <p className="text-sm text-destructive">{transferError}</p>
                )}

                <Button
                  type="submit"
                  disabled={!senderAccountNumber || !receiverLookup || !amount.trim() || Number(amount) <= 0}
                  className="w-full"
                >
                  Send Money
                </Button>
              </form>
            )}
          </CardContent>
        </Card>
      </main>

      <footer className="flex justify-between items-center px-8 py-4 text-sm text-muted-foreground/70 border-t border-border">
        <span>Wave Payment Platform</span>
        <span>{accounts.length} account{accounts.length !== 1 ? "s" : ""}</span>
      </footer>

      {(depositing || transferring) && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-background/80 backdrop-blur-sm animate-fade-in">
          <div className="bg-card px-10 py-9 text-center space-y-6 max-w-sm w-full mx-4 rounded-xl shadow-xl">
            <div className="w-10 h-10 mx-auto rounded-full border-2 border-primary/30 flex items-center justify-center">
              <div className="w-5 h-5 rounded-full border-2 border-primary border-t-transparent animate-a-spin" />
            </div>
            <div className="space-y-1">
              <p className="text-2xl font-mono font-bold text-foreground tracking-tight">
                {formatCurrency(depositing ? depositAmount : amount)}
              </p>
              <p className="text-sm text-muted-foreground">
                {depositing
                  ? accounts.find((a) => a.accountNumber === depositAccountNumber)?.name ?? "Account"
                  : `${accounts.find((a) => a.accountNumber === senderAccountNumber)?.name ?? "Sender"} \u2192 ${receiverLookup?.name ?? "Receiver"}`}
              </p>
            </div>
            <p className="text-xs text-muted-foreground/70">
              {depositing ? "Processing deposit" : "Processing transfer"}
            </p>
          </div>
        </div>
      )}
    </>
  )
}

import { useEffect, useState, useMemo, useCallback } from "react"
import {
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  flexRender,
  createColumnHelper,
  type SortingState,
} from "@tanstack/react-table"
import { ArrowLeft } from "lucide-react"
import { useSession } from "../lib/auth-client"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Badge } from "../components/ui/badge"
import { Skeleton } from "../components/ui/skeleton"
import { fetchTransactionsAction } from "@/actions/transaction.actions"
import type { ITransaction, IWalletTransaction, WaveResponse } from "@/types"
import { fetchAccountTransactionsAction } from "@/actions/account.actions"

type Filter = "all" | "success" | "failed" | "pending"

const formatBalance = (balance: number) =>
  new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(balance)

const formatDate = (iso: string) =>
  new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(iso))

export default function AccountTransactionsPage() {
  const { data: session } = useSession()
  const user = session!.user
  const [transactions, setTransactions] = useState<ITransaction[]>([])
  const [accounts, setAccounts] = useState<IWalletTransaction[]>([])
  const [accountsLoaded, setAccountsLoaded] = useState(false)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [filter, setFilter] = useState<Filter>("all")
  const [sorting, setSorting] = useState<SortingState>([{ id: "createdAt", desc: true }])

  const columnHelper = createColumnHelper<ITransaction>()

  const userAccountIds = useMemo(() => new Set(accounts.map((a) => a.id)), [accounts])

  const getDirection = useCallback(
    (tx: ITransaction): "in" | "out" | "self" => {
      if (tx.senderName === tx.receiverName) return "self"
      if (userAccountIds.has(tx.senderAccountNumber.toString())) return "in"
      if (userAccountIds.has(tx.receiverAccountNumber.toString())) return "in"
      return "out"
    },
    [userAccountIds],
  )

  const columns = useMemo(
    () => [
      columnHelper.accessor("createdAt", {
        header: "Date",
        cell: (info) => (
          <span className="text-sm text-muted-foreground whitespace-nowrap">
            {formatDate(info.getValue().toString())}
          </span>
        ),
      }),
      columnHelper.display({
        id: "direction",
        header: "",
        cell: ({ row }) => {
          const dir = getDirection(row.original)
          return (
            <div className="shrink-0 w-8 h-8 rounded-full flex items-center justify-center text-sm font-semibold bg-secondary text-secondary-foreground">
              {dir === "in" ? "\u2190" : dir === "self" ? "\u21C4" : "\u2192"}
            </div>
          )
        },
      }),
      columnHelper.accessor("senderName", {
        header: "Counterparty",
        cell: (info) => {
          const tx = info.row.original
          const dir = getDirection(tx)
          const label = dir === "self" ? "Deposit" : dir === "in" ? `From ${tx.senderName}` : `To ${tx.receiverName}`
          return (
            <div className="min-w-0">
              <p className="text-sm font-medium text-foreground truncate">{label}</p>
            </div>
          )
        },
      }),
      columnHelper.accessor("amount", {
        header: "Amount",
        cell: (info) => {
          const tx = info.row.original
          const dir = getDirection(tx)
          return (
            <span className={`text-sm font-mono font-semibold whitespace-nowrap ${
              dir === "in" ? "text-success" : "text-foreground"
            }`}>
              {dir === "in" ? "+" : dir === "out" ? "\u2212" : ""}{formatBalance(Number(tx.amount))}
            </span>
          )
        },
      }),
      columnHelper.accessor("status", {
        header: "Status",
        cell: (info) => (
          <Badge
            variant={info.getValue() === "success" ? "default" : info.getValue() === "failed" ? "destructive" : "secondary"}
            className="text-[10px] px-1.5 py-0 whitespace-nowrap"
          >
            {info.getValue()}
          </Badge>
        ),
      }),
    ],
    [columnHelper, getDirection],
  )

  const filtered = useMemo(
    () => (filter === "all" ? transactions : transactions.filter((tx) => tx.status === filter)),
    [transactions, filter],
  )

  const table = useReactTable({
    data: filtered,
    columns,
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
  })

  const fetchTransactions = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const res = await fetchTransactionsAction(user.id);
      if (!res.ok) throw new Error(res.error ?? `HTTP ${res.status}`)

      const sorted = (res.data ?? []).sort(
        (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
      )
      setTransactions(sorted)
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load transactions")
      setTransactions([])
    } finally {
      setLoading(false)
    }
  }, [user.id])

  const fetchAccounts = useCallback(async () => {
    try {
      const res = await fetchAccountTransactionsAction(user.id); 
      if (!res.ok) {
        throw new Error(res.error ?? `HTTP ${res.status}`)
      };

      setAccounts(res.data)
    } catch (error) {
      console.error("Error fetching account data:", error)
      setAccounts([])
    } finally {
      setAccountsLoaded(true)
    }
  }, [user.id])

  useEffect(() => {
    fetchAccounts()
  }, [fetchAccounts])

  useEffect(() => {
    if (accountsLoaded) fetchTransactions()
  }, [user.id, accountsLoaded])

  return (
    <>
      <header className="flex items-center justify-between flex-wrap gap-3 px-8 py-5 border-b border-border">
        <div className="flex items-center gap-3">
          <a
            href="/account"
            className="inline-flex items-center justify-center w-8 h-8 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
            aria-label="Back to Account"
          >
            <ArrowLeft className="size-4" />
          </a>
          <h1 className="text-xl font-semibold tracking-tight text-foreground">Transactions</h1>
        </div>
        <div className="flex items-center gap-3">
          <span className="text-sm text-muted-foreground">{user.email}</span>
        </div>
      </header>

      <main className="flex-1 mx-auto w-full max-w-4xl px-8 py-8 space-y-6">
        <div className="flex items-center gap-2">
          {(["all", "success", "pending", "failed"] as const).map((f) => (
            <Button
              key={f}
              variant={filter === f ? "default" : "outline"}
              size="sm"
              onClick={() => setFilter(f)}
              className="capitalize"
            >
              {f}
            </Button>
          ))}
        </div>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-4">
            <CardTitle className="text-sm font-medium">
              {filter === "all" ? "All Transactions" : `${filter.charAt(0).toUpperCase() + filter.slice(1)} Transactions`}
            </CardTitle>
            <span className="text-xs text-muted-foreground">{filtered.length} total</span>
          </CardHeader>
          <CardContent className="p-0">
            {loading && (
              <div className="space-y-3 p-6">
                {Array.from({ length: 5 }).map((_, i) => (
                  <Skeleton key={i} className="h-12 w-full rounded-md" />
                ))}
              </div>
            )}

            {error && !loading && (
              <div className="flex flex-col items-center gap-3 py-10 text-center px-6">
                <p className="text-sm text-muted-foreground">{error}</p>
                <Button variant="outline" size="sm" onClick={fetchTransactions}>
                  Retry
                </Button>
              </div>
            )}

            {!loading && !error && filtered.length === 0 && (
              <div className="py-10 text-center px-6">
                <p className="text-sm text-muted-foreground">
                  {transactions.length === 0
                    ? "No transactions yet. Deposit funds to get started."
                    : `No ${filter !== "all" ? filter : ""} transactions found.`}
                </p>
              </div>
            )}

            {!loading && !error && filtered.length > 0 && (
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead>
                    {table.getHeaderGroups().map((hg) => (
                      <tr key={hg.id} className="border-b border-border/50">
                        {hg.headers.map((header) => (
                          <th
                            key={header.id}
                            className="text-left text-xs font-medium text-muted-foreground px-4 py-3 cursor-pointer select-none hover:text-foreground transition-colors"
                            onClick={header.column.getToggleSortingHandler()}
                          >
                            <div className="flex items-center gap-1">
                              {flexRender(header.column.columnDef.header, header.getContext())}
                              {{
                                asc: " \u25B2",
                                desc: " \u25BC",
                              }[header.column.getIsSorted() as string] ?? null}
                            </div>
                          </th>
                        ))}
                      </tr>
                    ))}
                  </thead>
                  <tbody>
                    {table.getRowModel().rows.map((row) => (
                      <tr key={row.id} className="transition-colors hover:bg-surface-hover">
                        {row.getVisibleCells().map((cell) => (
                          <td key={cell.id} className="px-4 py-3.5 border-b border-border/30 last:border-0">
                            {flexRender(cell.column.columnDef.cell, cell.getContext())}
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </CardContent>
        </Card>
      </main>

      <footer className="flex justify-between items-center px-8 py-4 text-sm text-muted-foreground/70 border-t border-border">
        <span>Wave Payment Platform</span>
        <span>{filtered.length} transaction{filtered.length !== 1 ? "s" : ""}</span>
      </footer>
    </>
  )
}

