import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import { useState } from "react"
import { Eye, EyeOff, MoreVertical } from "lucide-react"
import { cn } from "../lib/utils"
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
} from "./ui/dropdown-menu"
import type { TBankAccountNumber } from "@/types"

interface WalletCardAccount {
  id: string
  name: string
  accountNumber: TBankAccountNumber
  balance: number
}

function formatBalance(b: number) {
  return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(b)
}

function maskNumber(num: string) {
  const prefix = "WAVE-"
  if (num.startsWith(prefix)) {
    const rest = num.slice(prefix.length)
    const vis = rest.slice(-4)
    const masked = rest.slice(0, -4).replace(/./g, "\u25CF")
    return `${masked}${masked ? " " : ""}${vis}`
  }
  if (num.length <= 4) return num
  const vis = num.slice(-4)
  return `${num.slice(0, -4).replace(/./g, "\u25CF")} ${vis}`
}

export default function WalletCard({
  account,
}: {
  account: WalletCardAccount
}) {
  const [showBalance, setShowBalance] = useState(true)

  return (
    <div className="group relative w-full aspect-[1.586/1] rounded-xl bg-gradient-to-br from-[oklch(0.35_0.15_165)] to-[oklch(0.22_0.12_165)] overflow-hidden shadow-lg shadow-black/20 transition-transform duration-500 ease-out hover:[transform:perspective(1200px)_rotateY(-3deg)_rotateX(1deg)] motion-reduce:hover:transform-none select-none">
      <div className="absolute inset-0 bg-gradient-to-br from-white/[0.08] via-white/[0.02] to-transparent pointer-events-none transition-opacity duration-700 group-hover:opacity-[0.15] motion-reduce:transition-none" />
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top_right,oklch(1_0_0_/_0.04),transparent_60%)] pointer-events-none" />

      <div className="relative z-10 flex flex-col justify-between h-full p-5 sm:p-6">
        <div className="flex items-start justify-between">
          <div className="w-10 h-7 rounded-[4px] bg-gradient-to-br from-[oklch(0.85_0.12_85)] to-[oklch(0.7_0.15_85)] shadow-inner flex items-center justify-center">
            <div className="w-6 h-4 rounded-[2px] border border-[oklch(0.6_0.1_85_/_0.5)] flex items-center justify-center">
              <div className="w-2 h-2 rounded-full border border-[oklch(0.6_0.1_85_/_0.4)]" />
            </div>
          </div>
          <div className="flex items-center gap-1">
            <button
              type="button"
              onClick={() => setShowBalance((v) => !v)}
              className="flex items-center justify-center w-8 h-8 rounded-full bg-white/10 hover:bg-white/20 transition-colors text-white/70 hover:text-white"
              aria-label={showBalance ? "Hide balance" : "Show balance"}
            >
              {showBalance ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
            </button>
            <div className="relative z-10">
              <DropdownMenu>
                <DropdownMenuTrigger className="flex z-10 items-center justify-center w-8 h-8 rounded-full bg-white/10 hover:bg-white/20 transition-colors text-white/70 hover:text-white">
                  <MoreVertical className="w-4 h-4" />
                </DropdownMenuTrigger>
                <DropdownMenuContent>
                  <DropdownMenuItem onClick={() => window.location.href = "/account/settings"}>
                    Edit
                  </DropdownMenuItem>
                  <DropdownMenuSeparator />
                  <DropdownMenuItem onClick={() => window.location.href = "/account/transactions"}>
                    Transactions
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          </div>
        </div>

        <div>
          <p className="text-[10px] sm:text-xs font-medium tracking-[0.2em] text-white/50 uppercase">
            Balance
          </p>
          <p
            className={cn(
              "mt-1 text-2xl sm:text-3xl font-semibold font-mono tracking-tight transition-all duration-300",
              !showBalance && "blur-lg select-none"
            )}
            aria-hidden={!showBalance}
          >
            {formatBalance(account.balance)}
          </p>
        </div>

        <div>
          <p className="text-xs sm:text-sm font-mono tracking-[0.15em] text-white/90">
            {account.balance}
          </p>
          <p className="mt-1 text-xs sm:text-sm font-medium text-white/50 truncate">
            {account.name}
          </p>
        </div>
      </div>
    </div>
  )
}

import { useState, useMemo } from "react"
import {
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  flexRender,
  createColumnHelper,
  type SortingState,
} from "@tanstack/react-table"
import { Badge } from "./ui/badge"
import { Skeleton } from "./ui/skeleton"
import type { ITransaction } from "@/types"

interface DataTableProps {
  data: ITransaction[]
  userAccountIds: Set<string>
  loading?: boolean
  emptyMessage?: string
}

const formatBalance = (b: number | string) =>
  new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(Number(b))

const formatDate = (iso: string) =>
  new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(iso))

type SortDir = "in" | "out" | "self"

export default function DataTable({ data, userAccountIds, loading, emptyMessage }: DataTableProps) {
  const columnHelper = createColumnHelper<ITransaction>()

  const getDirection = (tx: ITransaction): SortDir => {
    if (tx.senderName === tx.receiverName) return "self"
    if (userAccountIds.has(tx.receiverAccountNumber.toString()) && !userAccountIds.has(tx.senderAccountNumber.toString())) return "in"
    return "out"
  }

  const columns = useMemo(
    () => [
      columnHelper.accessor("createdAt", {
        header: "Date",
        cell: (info) => (
          <span className="text-sm text-muted-foreground whitespace-nowrap">
            {formatDate(info.getValue())}
          </span>
        ),
      }),
      columnHelper.display({
        id: "direction",
        header: "",
        cell: ({ row }) => {
          const dir = getDirection(row.original)
          return (
            <div className="shrink-0 w-8 h-8 rounded-full flex items-center justify-center text-sm font-semibold bg-secondary text-secondary-foreground">
              {dir === "in" ? "\u2190" : dir === "self" ? "\u21C4" : "\u2192"}
            </div>
          )
        },
      }),
      columnHelper.accessor("senderName", {
        header: "Counterparty",
        cell: (info) => {
          const tx = info.row.original
          const dir = getDirection(tx)
          const label = dir === "self" ? "Deposit" : dir === "in" ? `From ${tx.senderName}` : `To ${tx.receiverName}`
          return (
            <div className="min-w-0">
              <p className="text-sm font-medium text-foreground truncate">{label}</p>
            </div>
          )
        },
      }),
      columnHelper.accessor("amount", {
        header: "Amount",
        cell: (info) => {
          const tx = info.row.original
          const dir = getDirection(tx)
          return (
            <span className={`text-sm font-mono font-semibold whitespace-nowrap ${
              dir === "in" ? "text-success" : dir === "out" ? "text-foreground" : "text-foreground"
            }`}>
              {dir === "in" ? "+" : dir === "out" ? "\u2212" : ""}{formatBalance(tx.amount)}
            </span>
          )
        },
      }),
      columnHelper.accessor("status", {
        header: "Status",
        cell: (info) => (
          <Badge
            variant={info.getValue() === "success" ? "default" : info.getValue() === "failed" ? "destructive" : "secondary"}
            className="text-[10px] px-1.5 py-0 whitespace-nowrap"
          >
            {info.getValue()}
          </Badge>
        ),
      }),
    ],
    [userAccountIds],
  )

  const [sorting, setSorting] = useState<SortingState>([{ id: "createdAt", desc: true }])

  const table = useReactTable({
    data,
    columns,
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
  })

  if (loading) {
    return (
      <div className="space-y-3 p-4">
        {Array.from({ length: 5 }).map((_, i) => (
          <Skeleton key={i} className="h-10 w-full rounded-md" />
        ))}
      </div>
    )
  }

  if (data.length === 0) {
    return (
      <div className="py-10 text-center">
        <p className="text-sm text-muted-foreground">{emptyMessage ?? "No transactions yet."}</p>
      </div>
    )
  }

  return (
    <div className="overflow-x-auto">
      <table className="w-full">
        <thead>
          {table.getHeaderGroups().map((hg) => (
            <tr key={hg.id} className="border-b border-border/50">
              {hg.headers.map((header) => (
                <th
                  key={header.id}
                  className="text-left text-xs font-medium text-muted-foreground px-4 py-3 cursor-pointer select-none hover:text-foreground transition-colors"
                  onClick={header.column.getToggleSortingHandler()}
                >
                  <div className="flex items-center gap-1">
                    {flexRender(header.column.columnDef.header, header.getContext())}
                    {{
                      asc: " \u25B2",
                      desc: " \u25BC",
                    }[header.column.getIsSorted() as string] ?? null}
                  </div>
                </th>
              ))}
            </tr>
          ))}
        </thead>
        <tbody>
          {table.getRowModel().rows.map((row) => (
            <tr key={row.id} className="transition-colors hover:bg-surface-hover">
              {row.getVisibleCells().map((cell) => (
                <td key={cell.id} className="px-4 py-3 border-b border-border/30 last:border-0">
                  {flexRender(cell.column.columnDef.cell, cell.getContext())}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

