## 7. CLIENT INDEX.TS - PROXY SETUP

### File: `/home/coderx85/Projects/Work/.GITHUB/wave/client/index.ts` (33 lines)

```ts
import index from "./index.html"

const BACKEND_PORT = 3000;
const FRONTEND_PORT = 5173;

function proxyApi(req: Request): Promise<Response> {
  const url = new URL(req.url);
  const backendUrl = `http://localhost:${BACKEND_PORT}${url.pathname}${url.search}`;
  return fetch(backendUrl, { method: req.method, headers: req.headers, body: req.body });
}

Bun.serve({
  port: FRONTEND_PORT,
  routes: {
    "/api/*": {
      GET: proxyApi,
      POST: proxyApi,
      PUT: proxyApi,
      PATCH: proxyApi,
      DELETE: proxyApi,
      HEAD: proxyApi,
      OPTIONS: proxyApi,
    },
    "/*": index,
  },
  development: { hmr: true, console: true },
});
```

All `/api/*` requests are proxied to backend at `localhost:3000`. All other requests serve the SPA from `index.html`.

